//! Monster info on hover (Settings > Game > Interface): under a monster's name, its level,
//! element, race and size, as "Lv 1 · Water 1 · Plant · Medium", and Boss or MVP. The table
//! (mobinfo_db.rs) is generated by tools/mobinfo from the server's mob_db, custom monsters
//! included; the level the server sends wins over the table's.

use egui::Color32;

use crate::mobinfo_db::MOBS;

const ELEMENTS: [&str; 10] = ["Neutral", "Water", "Earth", "Fire", "Wind", "Poison", "Holy", "Shadow", "Ghost", "Undead"];
const RACES: [&str; 10] = ["Formless", "Undead", "Brute", "Plant", "Insect", "Fish", "Demon", "Demi-Human", "Angel", "Dragon"];
const SIZES: [&str; 3] = ["Small", "Medium", "Large"];

/// The colour each element's line is drawn in (pale, so it reads over any ground).
const COLORS: [(u8, u8, u8); 10] = [
    (225, 225, 225), // neutral
    (130, 195, 255), // water
    (215, 180, 120), // earth
    (255, 140, 100), // fire
    (150, 240, 170), // wind
    (200, 150, 235), // poison
    (255, 245, 170), // holy
    (185, 160, 215), // shadow
    (190, 220, 230), // ghost
    (175, 200, 160), // undead
];

/// What the table knows of a monster.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct MobInfo {
    pub level: u16,
    pub element: u8,
    pub element_level: u8,
    pub race: u8,
    pub size: u8,
    /// 0 normal, 1 boss, 2 MVP.
    pub rank: u8,
}

pub fn lookup(class: u16) -> Option<MobInfo> {
    let i = MOBS.binary_search_by_key(&class, |m| m.0).ok()?;
    let (_, level, element, element_level, race, size, rank) = MOBS[i];
    Some(MobInfo { level, element, element_level, race, size, rank })
}

/// The line under a monster's name and its colour; `level` is the server's (0 if it sent
/// none).
pub fn line(class: u16, level: u16) -> Option<(String, Color32)> {
    let m = lookup(class)?;
    let level = if level > 0 { level } else { m.level };
    let name = |names: &[&'static str], i: u8| -> &'static str { names.get(i as usize).copied().unwrap_or("?") };
    let mut text = format!("Lv {level} · {} {} · {} · {}", name(&ELEMENTS, m.element), m.element_level, name(&RACES, m.race), name(&SIZES, m.size));
    match m.rank {
        2 => text.push_str(" · MVP"),
        1 => text.push_str(" · Boss"),
        _ => {}
    }
    let (r, g, b) = COLORS.get(m.element as usize).copied().unwrap_or(COLORS[0]);
    Some((text, Color32::from_rgb(r, g, b)))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_table_is_sorted_for_lookup() {
        assert!(MOBS.windows(2).all(|w| w[0].0 < w[1].0));
    }

    #[test]
    fn a_poring_reads_as_the_original_describes_it() {
        let (text, _) = line(1002, 0).unwrap();
        assert_eq!(text, "Lv 1 · Water 1 · Plant · Medium");
        // The server's level wins.
        assert!(line(1002, 7).unwrap().0.starts_with("Lv 7 ·"));
    }

    #[test]
    fn bosses_and_mvps_say_so_and_custom_monsters_are_known() {
        assert!(line(1039, 0).unwrap().0.ends_with(" · MVP"), "Baphomet");
        assert!(line(1096, 0).unwrap().0.ends_with(" · Boss"), "Angeling");
        assert!(lookup(31900).is_some(), "Twin Flames: Ashigaru Raider");
        assert!(line(1, 0).is_none());
    }
}
